src='''def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for q in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    a,b=q
                    if 0 <= a < h and 0 <= b < w and q not in seen and grid[a][b] == color:
                        seen.add(q); stack.append(q)
            comps.append((color, cells))
    def shape(cells):
        pts = [(r-min(x for x,y in cells), c-min(y for x,y in cells)) for r,c in cells]
        variants=[]
        for flip in (1,-1):
            for rot in range(4):
                out=[]
                for x,y in pts:
                    if flip == -1: y=-y
                    for _ in range(rot): x,y=y,-x
                    out.append((x,y))
                mr=min(x for x,y in out); mc=min(y for x,y in out)
                variants.append(tuple(sorted((x-mr,y-mc) for x,y in out)))
        return min(variants)
    colored = {}
    for color,cells in comps:
        if color != 1:
            colored.setdefault(shape(cells), color)
    out=[row[:] for row in grid]
    for color,cells in comps:
        if color == 1:
            target=colored.get(shape(cells))
            if target is not None:
                for r,c in cells: out[r][c]=target
    return out
'''
